            'fr' => array(
                'meta_title' => 'OANDA vs IG (2026) : quel courtier devriez-vous choisir ?',
                'meta_description' => 'OANDA vs IG comparés sur la réglementation, l\'historique, les coûts et les plateformes -- selon notre méthodologie publiée, et non selon des arguments marketing. Découvrez lequel correspond à votre style de trading.',
                'intro' => 'OANDA et IG sont deux courtiers établis de longue date, tous deux soumis à plusieurs régulations, dont la réputation s\'est construite sur des décennies plutôt que sur une arrivée récente sur le marché : IG est actif depuis 1974, OANDA depuis 1996. Ce sentiment partagé de longévité institutionnelle explique pourquoi les deux sont si souvent comparés, mais ils se distinguent nettement en matière de transparence : IG publie un spread principal confirmé et un dépôt minimum documenté proche de zéro, tandis que les données en notre possession sur OANDA ne permettent pas de confirmer son spread.',
                'verdict' => 'Selon notre méthodologie publiée, IG obtient une note globale de 4.13/5 contre 4.03/5 pour OANDA, un écart suffisamment faible pour que leur classement s\'inverse selon ce que vous privilégiez. L\'avantage d\'IG se concentre sur les coûts et l\'historique : son spread EUR/USD de 0.6 pips, documenté dans nos données, est confirmé et serré, ce qui lui vaut une note de coûts de 4.76/5, et sa fondation en 1974 lui assure une note parfaite de 5/5 pour l\'historique, la plus élevée de tous les courtiers que nous avons comparés à ce jour. OANDA répond par une meilleure note de réglementation (5.0/5 contre 3.4/5 pour IG), reflétant un éventail plus large de juridictions individuelles : la NFA et la CFTC américaines, la CIRO canadienne et la MAS singapourienne, aux côtés de l\'ASIC, face aux licences directes CySEC et FCA d\'IG et à sa mention plus large mais moins précisément détaillée de « +9 autres Tier-1 ». Les deux courtiers sont à égalité pour l\'étendue de leurs plateformes (3.4/5 chacun, correspondant à trois plateformes prises en charge chacun), et tous deux proposent un dépôt minimum pratiquement négligeable : un dépôt minimum documenté de 1 £ pour IG, contre une politique sans dépôt minimum pour OANDA.',
                'choose_a_heading' => 'Choisissez OANDA si...',
                'choose_a_point_1' => 'Vous souhaitez un éventail plus large de juridictions individuelles de type Tier-1 : OANDA détient la NFA et la CFTC américaines, la CIRO canadienne, la MAS singapourienne et l\'ASIC, ce qui se reflète dans sa note de réglementation de 5.0/5 contre 3.4/5 pour IG.',
                'choose_a_point_2' => 'Vous avez spécifiquement besoin d\'une couverture réglementaire américaine ou canadienne : OANDA est directement enregistré auprès de la NFA et de la CFTC (États-Unis) ainsi que de la CIRO (Canada), alors que la présence réglementaire documentée d\'IG ne mentionne aucune de ces entités.',
                'choose_a_point_3' => 'Vous souhaitez ouvrir un compte sans aucun dépôt minimum : OANDA n\'en exige aucun, alors que le minimum documenté d\'IG, bien que faible, est de 1 £.',
                'choose_b_heading' => 'Choisissez IG si...',
                'choose_b_point_1' => 'Un spread principal confirmé et serré est important pour vous : le spread EUR/USD de 0.6 pips d\'IG, dans nos données, est confirmé de manière indépendante et lui vaut une note de coûts de 4.76/5 ; le spread d\'OANDA n\'est pas confirmé dans nos données, de sorte qu\'une comparaison directe des coûts n\'est pas possible à partir de nos données.',
                'choose_b_point_2' => 'L\'historique d\'exploitation est important pour vous : IG est actif depuis 1974, soit 22 ans de plus qu\'OANDA, ce qui lui vaut une note parfaite de 5/5 pour l\'historique.',
                'choose_b_point_3' => 'Vous souhaitez une licence CySEC confirmée en plus de la FCA : IG détient les deux directement (309/16 et 195355) ; OANDA détient la FCA (542574) mais pas la CySEC.',
                'choose_b_point_4' => 'Vous souhaitez accéder au spread betting, et non seulement aux CFD : IG propose le spread betting au Royaume-Uni et en Irlande via une entité distincte, un produit qu\'OANDA ne propose pas.',
                'worth_knowing_heading' => 'Bon à savoir avant de vous décider',
                'worth_knowing' => 'OANDA a été racheté par FTMO, la société tchèque de trading pour compte propre (« funded trader »), auprès de CVC Capital Partners, avec effet au 1er décembre 2025 ; FTMO indique qu\'il exploitera OANDA comme une activité autonome, mais ce changement de propriété est très récent et il convient de vérifier que le service n\'en a pas été affecté avant de vous y fier. Les données en notre possession sur le spread d\'OANDA ne sont pas confirmées, ce qui explique l\'absence de note de coûts directe pour ce courtier dans notre méthodologie ; considérez toute affirmation tierce sur le « spread d\'OANDA » avec la même prudence tant qu\'OANDA ne publie pas de chiffre précis. Les sources divergent également sur la question de savoir si OANDA propose un compte islamique ou sans swap : certains comparateurs le suggèrent, tandis qu\'au moins une source spécifique au Royaume-Uni affirme qu\'OANDA Europe Limited n\'en propose pas. Cette contradiction non résolue, que nous n\'avons pas pu trancher dans nos recherches. IG, en revanche, dispose d\'une structure de compte clairement documentée, bien que son barème de frais sur CFD reflète spécifiquement son entité britannique soumise à la FCA ; le barème de frais de son entité chypriote soumise à la CySEC n\'a pas été vérifié séparément.',
                'faq_1_q' => 'OANDA ou IG est-il préférable pour les débutants ?',
                'faq_1_a' => 'Les deux offrent un seuil d\'entrée pratiquement négligeable : le dépôt minimum documenté d\'IG est de 1 £, et OANDA n\'en exige aucun. Le spread confirmé et serré d\'IG (0.6 pips) donne à un débutant une vision plus claire des coûts dès le départ ; le spread d\'OANDA n\'est pas confirmé de manière indépendante, de sorte qu\'il vous faudra vérifier directement sa tarification actuelle avant de comparer les coûts.',
                'faq_2_q' => 'Lequel des deux, OANDA ou IG, a le plus long historique ?',
